DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['workouts', 'workout_exercises', 'workout_sets', 'nutrition_logs', 'water_logs', 'weight_measurements', 'daily_checkins', 'daily_steps'] LOOP BEGIN EXECUTE format('ALTER TABLE public.%I REPLICA IDENTITY FULL', t); EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'replica identity full failed for %: %', t, SQLERRM; END; IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t) THEN BEGIN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t); EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'realtime add failed for %: %', t, SQLERRM; END; END IF; END LOOP; END; $$;
